CREATE OR REPLACE FUNCTION public.perform_flowers(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare tx int := (p_target->>'x')::int; ty int := (p_target->>'y')::int; v_n int;
begin
  v_n := flowers_on(p_world, tx, ty);
  if v_n <= 0 then return; end if;
  perform gather(p_world, p_uid, 'wildflowers', v_n, product_ql(skill_of(p_world, p_uid, 'foraging')));
  perform land_set_data(p_world, tx, ty, land_data(p_world, tx, ty) | flowers_picked()::int);
  perform land_announce(p_world, tx, ty);
  perform skill_raise(p_world, p_uid, 'foraging', 1);
  perform journal_note(p_world, p_uid, 'flowers:' || season_at(now()));
  perform tell(p_world, p_uid, 'Picked: ' || v_n
    || case when v_n = 1 then ' wildflower' else ' wildflowers' end
    || '. Flowers again in spring.', 'event');
end $function$
